INSERT INTO scenario_bank (scenario_id, framework_id, dimension_id, dimension_name, target_boundary, target_lower_level, target_upper_level, stem, context_tags, status, source_attribution)
VALUES ('CFT-HC-AD-01', 'teacher-competency', 'tc-human-centered', 'Human-Centered Mindset', 'acquire-deepen', 'Acquire', 'Deepen', 'Your head of department asks everyone to trial an AI-powered marking assistant that provides automated feedback on student essays. Before it goes live with students, what would you do?', '{"subject_area":"universal","institution_level":"universal","institution_type":"universal","region":"universal"}'::jsonb, 'draft', '{"source_framework":"UNESCO AI Competency Framework for Teachers","source_licence":"CC BY-SA 3.0 IGO","content_type":"derivative","attribution_text":"Based on the UNESCO AI Competency Framework for Teachers (2024). Scenarios created by ReasonLens.","share_alike_applies":true}'::jsonb);

INSERT INTO scenario_bank (scenario_id, framework_id, dimension_id, dimension_name, target_boundary, target_lower_level, target_upper_level, stem, context_tags, status, source_attribution)
